"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5026],{89780:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ResearchService","desc":"Authoritative owner of the shared, session-only Research Bench state. Handles\\nReqResearchEnqueue / ReqResearchCancel / ReqResearchRefuel (one call per\\nhold-to-refuel release, clamped to the pool; bench fuel has no cap) /\\nReqResearchSnapshot, and ReqResearchHold: while any player holds REFUEL the\\nburn and the job timer freeze for everyone (`state.frozen`); a holder whose\\nrelease never arrives expires after HOLD_TIMEOUT or on leave. It\\nruns a Heartbeat tick that advances the active job and burns fuel, auto-starts\\nthe next queued job on completion (firing Signals.OnResearchLevelUp), refunds\\ncancelled jobs into the global MaterialPool, and broadcasts ResearchStateUpdate. Boot is\\nsplit from definition (like PerkManager): require() this ModuleScript, then call\\nInitialize() once \u2014 see ResearchSystemLoader.server.luau.","realm":["Server"],"source":{"line":18,"path":"src/ServerStorage/SharedModules/ResearchService.luau"}}')}}]);